package clusterdata.datatypes;

import java.util.Objects;

public class TaskEvent {
    public long timestamp;
    public String missingInfo;
    public long jobId;
    public int taskIndex;
    public String machineId;
    public int eventType;
    public String userName;
    public int schedulingClass;
    public int priority;
    public double cpuRequest;
    public double ramRequest;
    public double diskRequest;
    public int differentMachineConstraint;

    public TaskEvent() {}

    public static TaskEvent fromString(String line) {
        String[] tokens = line.split(",", -1);
        TaskEvent event = new TaskEvent();
        event.timestamp = Long.parseLong(tokens[0]);
        event.missingInfo = tokens[1];
        event.jobId = Long.parseLong(tokens[2]);
        event.taskIndex = Integer.parseInt(tokens[3]);
        event.machineId = tokens[4];
        event.eventType = Integer.parseInt(tokens[5]);
        // Other fields can be parsed if needed, but let's at least parse these.
        return event;
    }

    @Override
    public String toString() {
        return "TaskEvent{" +
                "timestamp=" + timestamp +
                ", jobId=" + jobId +
                ", eventType=" + eventType +
                '}';
    }
}

