package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.sink.RichSinkFunction;
import org.apache.flink.streaming.api.functions.source.SourceFunction;
import org.apache.flink.util.Collector;

import java.io.*;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        final int sesssize = params.getInt("sesssize", 600); // in seconds

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        DataStream<TaskEvent> taskStream = env.addSource(AppBase.taskSourceOrTest(new TaskEventSource(taskInput)))
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<TaskEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((event, timestamp) -> event.timestamp)
                );

        DataStream<JobEvent> jobStream = env.addSource(AppBase.jobSourceOrTest(new JobEventSource(jobInput)))
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<JobEvent>forMonotonousTimestamps()
                                .withTimestampAssigner((event, timestamp) -> event.timestamp)
                );

        DataStream<Tuple2<Long, Integer>> result = taskStream
                .keyBy(event -> event.jobId)
                .connect(jobStream.keyBy(event -> event.jobId))
                .process(new LongestStageProcess(sesssize * 1000000L));

        result.addSink(AppBase.sinkOrTest(new FileSink(outputPath)));

        env.execute("LongestSessionPerJob");
    }

    public static class TaskEventSource implements SourceFunction<TaskEvent> {
        private final String path;
        private volatile boolean running = true;

        public TaskEventSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            if (path == null) return;
            try (GZIPInputStream gzipStream = new GZIPInputStream(new FileInputStream(path));
                 BufferedReader reader = new BufferedReader(new InputStreamReader(gzipStream))) {
                String line;
                while (running && (line = reader.readLine()) != null) {
                    if (line.trim().isEmpty()) continue;
                    try {
                        ctx.collect(TaskEvent.fromString(line));
                    } catch (Exception e) {
                        // skip malformed lines
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    public static class JobEventSource implements SourceFunction<JobEvent> {
        private final String path;
        private volatile boolean running = true;

        public JobEventSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            if (path == null) return;
            try (GZIPInputStream gzipStream = new GZIPInputStream(new FileInputStream(path));
                 BufferedReader reader = new BufferedReader(new InputStreamReader(gzipStream))) {
                String line;
                while (running && (line = reader.readLine()) != null) {
                    if (line.trim().isEmpty()) continue;
                    try {
                        ctx.collect(JobEvent.fromString(line));
                    } catch (Exception e) {
                        // skip malformed lines
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    public static class LongestStageProcess extends KeyedCoProcessFunction<Long, TaskEvent, JobEvent, Tuple2<Long, Integer>> {
        private final long gap;
        private transient ValueState<Integer> currentStageTasks;
        private transient ValueState<Long> lastSubmitTimestamp;
        private transient ValueState<Integer> maxStageTasks;
        private transient ValueState<Boolean> jobFinished;

        public LongestStageProcess(long gap) {
            this.gap = gap;
        }

        @Override
        public void open(Configuration parameters) throws Exception {
            currentStageTasks = getRuntimeContext().getState(new ValueStateDescriptor<>("currentStageTasks", Integer.class));
            lastSubmitTimestamp = getRuntimeContext().getState(new ValueStateDescriptor<>("lastSubmitTimestamp", Long.class));
            maxStageTasks = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStageTasks", Integer.class));
            jobFinished = getRuntimeContext().getState(new ValueStateDescriptor<>("jobFinished", Boolean.class));
        }

        @Override
        public void processElement1(TaskEvent event, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            if (event.eventType != 0) return; // SUBMIT

            Integer current = currentStageTasks.value();
            Long last = lastSubmitTimestamp.value();
            Integer max = maxStageTasks.value();

            if (last == null) {
                current = 1;
            } else {
                if (event.timestamp - last > gap) {
                    if (max == null || current > max) {
                        max = current;
                    }
                    current = 1;
                } else {
                    current = (current == null ? 0 : current) + 1;
                }
            }

            currentStageTasks.update(current);
            lastSubmitTimestamp.update(event.timestamp);
            maxStageTasks.update(max == null ? 0 : max);
        }

        @Override
        public void processElement2(JobEvent event, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            // FINISH(4), KILL(5), LOST(6)
            if (event.eventType == 4 || event.eventType == 5 || event.eventType == 6) {
                jobFinished.update(true);
                ctx.timerService().registerEventTimeTimer(event.timestamp + 1);
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
            if (Boolean.TRUE.equals(jobFinished.value())) {
                Integer current = currentStageTasks.value();
                Integer max = maxStageTasks.value();

                if (current != null) {
                    if (max == null || current > max) {
                        max = current;
                    }
                }

                if (max != null && max > 0) {
                    out.collect(new Tuple2<>(ctx.getCurrentKey(), max));
                }

                currentStageTasks.clear();
                lastSubmitTimestamp.clear();
                maxStageTasks.clear();
                jobFinished.clear();
            }
        }
    }

    public static class FileSink extends RichSinkFunction<Tuple2<Long, Integer>> {
        private final String path;
        private transient PrintWriter writer;

        public FileSink(String path) {
            this.path = path;
        }

        @Override
        public void open(Configuration parameters) throws Exception {
            if (path != null) {
                writer = new PrintWriter(new BufferedWriter(new FileWriter(path)));
            }
        }

        @Override
        public void invoke(Tuple2<Long, Integer> value, Context context) throws Exception {
            if (writer != null) {
                writer.println("(" + value.f0 + "," + value.f1 + ")");
                writer.flush();
            }
        }

        @Override
        public void close() throws Exception {
            if (writer != null) {
                writer.close();
            }
        }
    }
}
